<?= view('layout/header', ['title' => 'Customers']) ?><h1>Customers</h1><p><a class="button" href="<?= site_url('customers/new') ?>">Add customer</a></p><div class="panel table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= esc($item['full_name']) ?></td><td><?= esc($item['email']) ?></td><td><?= esc($item['phone'] ?: '—') ?></td><td><div class="actions"><a href="<?= site_url('customers/' . $item['id'] . '/edit') ?>">Edit</a><form method="post" action="<?= site_url('customers/' . $item['id'] . '/archive') ?>" onsubmit="return confirm('Archive this customer?')"><?= csrf_field() ?><button class="danger">Archive</button></form></div></td></tr><?php endforeach ?><?php if (! $items): ?><tr><td colspan="4">No customers yet.</td></tr><?php endif ?></tbody></table></div><?= view('layout/footer') ?>
